//! Differential parity against the real TS AI: the main parity guarantee.
//!
//! `fixtures/differential.json` (generated by `scripts/differential.ts`) holds
//! full matches played by the TS engine. At every decision point the generator
//! builds six parts from the acting seat's (optionally augmented) view:
//!
//! ```text
//! 0 rank      rankMoves for neutral + Rita/Ned/Grandpa options, with topMove
//! 1 notation  encodeForLlm(view, legal, { ranking, notes })
//! 2 bid       JSON.stringify(bidRollouts(view, legal)) while bidding
//! 3 play      JSON.stringify(playRollouts(view, legal))
//! 4 jev       the Jev request body of buildDecisionQuestion
//! 5 memory    seat memory JSON, situationLine, momentSalience
//! ```
//!
//! The fixture keeps the engine `fnv1a` of each part per point (to locate a
//! mismatch to one part of one decision) and, per game, the SHA-256 of every
//! joined point string in order (the byte-identity guarantee).
//!
//! On a mismatch it prints the seed, the decision index, the part and the Rust
//! text; the TS side is `bun run crates/euchre-ai/scripts/differential.ts --dump
//! <seed> <index> <part>`.

use euchre_ai::ai_seat::memory::{
    absorb_public_state, empty_memory, moment_salience, situation_line,
};
use euchre_ai::ai_seat::state::AiSeatHandMemory;
use euchre_ai::decision_context::{
    DecisionQuestionParams, build_decision_question, jev_request_body,
};
use euchre_ai::js::stringify;
use euchre_ai::notation::{EncodeParams, encode_for_llm};
use euchre_ai::{
    BidRolloutParams, HeuristicOptions, PlayRolloutParams, RankParams, bid_rollouts, play_rollouts,
    rank_moves, top_move,
};
use euchre_engine::{
    EngineConfigOverrides, GameInit, GamePhase, GameStatus, LegalMove, Mulberry32, ObservationKind,
    ObservationTiming, PublicGameView, Seat, TableObservation, TableRules, fnv1a, legal_moves,
    project, try_advance, try_apply, try_create_game,
};
use euchre_protocol::serde_util::js_number_string;
use euchre_protocol::{PersonaConfig, default_personas};
use serde::Deserialize;
use serde_json::{Map, Value};
use sha2::{Digest, Sha256};

const FIXTURE: &str = include_str!("fixtures/differential.json");
const SEP: &str = "\n\u{a7}\n";
const PART_NAMES: [&str; 6] = ["rank", "notation", "bid", "play", "jev", "memory"];

/// Games are split into this many `#[test]`s so they replay in parallel.
const SHARDS: usize = 8;

#[derive(Deserialize)]
struct Fixture {
    games: Vec<GameFixture>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct GameFixture {
    seed: String,
    game_id: String,
    cfg: Option<EngineConfigOverrides>,
    first_dealer: Option<Seat>,
    picker: String,
    augment: bool,
    decisions: usize,
    final_turn_id: String,
    sha256: String,
    points: Vec<Vec<u32>>,
}

fn personas() -> Vec<PersonaConfig> {
    default_personas().into_iter().map(|a| a.persona).collect()
}

fn pick(
    kind: &str,
    rnd: &mut Mulberry32,
    view: &PublicGameView,
    seat: Seat,
    legal: &[LegalMove],
) -> LegalMove {
    let random = |rnd: &mut Mulberry32| {
        let i = (rnd.next_f64() * legal.len() as f64).floor() as usize;
        legal[i].clone()
    };
    let heuristic = || {
        let id = top_move(
            RankParams::new(view)
                .with_hand(&view.hand)
                .with_legal(legal),
        );
        legal
            .iter()
            .find(|m| Some(&m.id) == id.as_ref())
            .unwrap_or(&legal[0])
            .clone()
    };
    match kind {
        "random" => random(rnd),
        "heuristic" => heuristic(),
        "mixed" => {
            if seat.get() == 0 {
                random(rnd)
            } else {
                heuristic()
            }
        }
        "passHeavy" => {
            let bidding = matches!(view.phase, GamePhase::BidRound1 | GamePhase::BidRound2);
            if bidding
                && rnd.next_f64() < 0.8
                && let Some(pass) = legal.iter().find(|m| m.id == "pass")
            {
                return pass.clone();
            }
            heuristic()
        }
        "alone" => match legal.iter().find(|m| m.id.ends_with("+alone")) {
            Some(m) => m.clone(),
            None => random(rnd),
        },
        other => panic!("unknown picker {other}"),
    }
}

fn rank_part(
    view: &PublicGameView,
    legal: &[LegalMove],
    game_to: f64,
    personas: &[PersonaConfig],
) -> String {
    let mut presets = vec![HeuristicOptions {
        aggression: None,
        risk: None,
        game_to: None,
    }];
    for p in personas {
        presets.push(HeuristicOptions {
            aggression: Some(p.aggression),
            risk: Some(p.risk),
            game_to: Some(game_to),
        });
    }
    presets
        .into_iter()
        .map(|opts| {
            let params = RankParams::new(view)
                .with_hand(&view.hand)
                .with_legal(legal)
                .with_opts(opts);
            let ranked = rank_moves(params);
            let top = top_move(params).unwrap_or_else(|| "null".to_owned());
            let mut line: String = ranked
                .iter()
                .map(|r| format!("{}|{}|{};", r.id, js_number_string(r.score), r.why))
                .collect();
            line.push_str(&format!("top={top}"));
            line
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn record<T: serde::Serialize>(pairs: &[(String, T)]) -> String {
    let mut map = Map::new();
    for (k, v) in pairs {
        map.insert(k.clone(), serde_json::to_value(v).unwrap());
    }
    stringify(&Value::Object(map))
}

struct PointInput<'a> {
    view: &'a PublicGameView,
    legal: &'a [LegalMove],
    memory: &'a AiSeatHandMemory,
    seat: Seat,
    game_to: f64,
    n: usize,
    personas: &'a [PersonaConfig],
}

fn parts(p: PointInput<'_>) -> [String; 6] {
    let PointInput {
        view,
        legal,
        memory,
        seat,
        game_to,
        n,
        personas,
    } = p;
    let neutral = rank_moves(
        RankParams::new(view)
            .with_hand(&view.hand)
            .with_legal(legal),
    );
    let bidding = matches!(view.phase, GamePhase::BidRound1 | GamePhase::BidRound2);
    let notation = encode_for_llm(EncodeParams {
        view,
        legal,
        ranking: Some(&neutral),
        notes: Some(&memory.bid_history),
    });
    let bid = if bidding {
        record(&bid_rollouts(BidRolloutParams::new(view, legal)).unwrap())
    } else {
        String::new()
    };
    let play = record(&play_rollouts(PlayRolloutParams::new(view, legal)).unwrap());
    let question = build_decision_question(DecisionQuestionParams {
        view,
        legal,
        persona: &personas[n % 3],
    })
    .unwrap();
    let jev = jev_request_body(&question);
    let mem = format!(
        "{}\n{}\n{}",
        stringify(&serde_json::to_value(memory).unwrap()),
        situation_line(view, seat),
        js_number_string(moment_salience(view, game_to))
    );
    [
        rank_part(view, legal, game_to, personas),
        notation,
        bid,
        play,
        jev,
        mem,
    ]
}

fn kind_of(phase: GamePhase) -> ObservationKind {
    match phase {
        GamePhase::Cutting => ObservationKind::Cut,
        GamePhase::BidRound1 => ObservationKind::Bid1,
        GamePhase::BidRound2 => ObservationKind::Bid2,
        GamePhase::DealerDiscard => ObservationKind::Discard,
        _ => ObservationKind::Play,
    }
}

/// Replays one game; returns a mismatch description, if any.
fn replay(game: &GameFixture, personas: &[PersonaConfig]) -> Option<String> {
    let mut state = try_create_game(GameInit {
        game_id: game.game_id.clone(),
        seed: game.seed.clone(),
        cfg: game.cfg,
        internal_token: None,
        first_dealer: game.first_dealer,
    })
    .unwrap();
    let mut rnd = Mulberry32::new(fnv1a(&game.seed));
    let mut memories: Vec<AiSeatHandMemory> = (0..4).map(|_| empty_memory(0)).collect();
    let mut observations: Vec<TableObservation> = Vec::new();
    let mut sha = Sha256::new();
    let mut n = 0usize;
    let mut steps = 0usize;
    while state.status == GameStatus::Active {
        steps += 1;
        assert!(steps < 20000, "{}: budget exhausted", game.seed);
        let Some(seat) = state.hand.turn_seat else {
            state = try_advance(&state).unwrap().state;
            continue;
        };
        let mut view = project(&state, seat);
        if game.augment {
            view.rules = Some(TableRules {
                stick_the_dealer: state.cfg.stick_the_dealer,
                require_natural_trump: state.cfg.require_natural_trump.unwrap_or(false),
            });
            view.observations = Some(observations.clone());
        }
        let legal = view.legal.clone();
        assert_eq!(legal, legal_moves(&state, seat));
        absorb_public_state(&mut memories[seat.index()], &view);
        let ps = parts(PointInput {
            view: &view,
            legal: &legal,
            memory: &memories[seat.index()],
            seat,
            game_to: f64::from(state.cfg.game_to),
            n,
            personas,
        });
        let Some(expected) = game.points.get(n) else {
            return Some(format!(
                "{}: Rust has more decisions than TS ({})",
                game.seed, game.decisions
            ));
        };
        for (k, part) in ps.iter().enumerate() {
            if fnv1a(part) != expected[k] {
                return Some(format!(
                    "{} decision {n} part {k} ({}) differs; TS: bun run crates/euchre-ai/scripts/differential.ts --dump {} {n} {k}\n--- Rust ---\n{part}",
                    game.seed, PART_NAMES[k], game.seed
                ));
            }
        }
        sha.update(ps.join(SEP).as_bytes());
        sha.update(b"\n");
        let chosen = pick(&game.picker, &mut rnd, &view, seat, &legal);
        observations.push(TableObservation {
            hand_no: state.hand.hand_no,
            seat,
            kind: kind_of(state.hand.phase),
            action: chosen.label.clone(),
            elapsed_ms: (seat.get() == 0).then(|| 300 + ((n as u64 * 7919) % 5000)),
            timing: if seat.get() == 0 {
                ObservationTiming::HumanObserved
            } else {
                ObservationTiming::ComputerPaced
            },
        });
        while observations.len() > 40 {
            observations.remove(0);
        }
        n += 1;
        state = try_apply(&state, seat, chosen.mv, None).unwrap().state;
    }
    if n != game.decisions {
        return Some(format!(
            "{}: {n} decisions, TS had {}",
            game.seed, game.decisions
        ));
    }
    if state.turn_id != game.final_turn_id {
        return Some(format!("{}: final turnId differs", game.seed));
    }
    let digest = hex::encode(sha.finalize());
    if digest != game.sha256 {
        return Some(format!(
            "{}: sha256 differs with equal part hashes",
            game.seed
        ));
    }
    None
}

fn shard(index: usize) {
    let fixture: Fixture = serde_json::from_str(FIXTURE).unwrap();
    let personas = personas();
    let mut failures = Vec::new();
    for (i, game) in fixture.games.iter().enumerate() {
        if i % SHARDS != index {
            continue;
        }
        if let Some(f) = replay(game, &personas) {
            failures.push(f);
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

#[test]
fn fixture_covers_every_decision_kind() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    let coverage = &fixture["coverage"];
    for key in [
        "cutting",
        "bid_round_1",
        "bid_round_2",
        "dealer_discard",
        "trick_play",
        "sitting",
        "loner_question",
        "support_question",
        "stick_the_dealer",
        "natural_trump",
        "observations",
    ] {
        assert!(coverage[key].as_u64().unwrap_or(0) > 0, "no {key} points");
    }
    let total: usize = fixture["games"]
        .as_array()
        .unwrap()
        .iter()
        .map(|g| g["decisions"].as_u64().unwrap() as usize)
        .sum();
    assert!(total >= 1000, "only {total} points");
}

